local function Slug(s) return s:gsub('[\128-\255]',''):lower():gsub('[^a-z0-9%s%-]',''):gsub('%s+','-') end
local byTitle={}
for _,e in ipairs(D.entries) do byTitle[e.kind..'/'..e.title]=e;for _,a in ipairs(e.aliases or {}) do byTitle[e.kind..'/'..a]=e end end
for _,a in ipairs(additions) do
    local old=byTitle[a.kind..'/'..a.title]
    if not old then for _,alias in ipairs(a.aliases) do if byTitle[a.kind..'/'..alias] then old=byTitle[a.kind..'/'..alias];break end end end
    if old then
        old.fieldSources=old.fieldSources or {}
        for field,text in pairs(a.fields) do if not old.fields[field] or old.fields[field]=='UNKNOWN' then old.fields[field]=text;old.fieldSources[field]=a.sourceURL end end
        old.region=a.region or old.region;old.period=a.period or old.period;old.zoneCatalog=a.region and true or old.zoneCatalog
        local seen={};for _,alias in ipairs(old.aliases or {old.title}) do seen[alias]=true end
        old.aliases=old.aliases or {old.title};for _,alias in ipairs(a.aliases) do if not seen[alias] then old.aliases[#old.aliases+1]=alias;seen[alias]=true end end
    else
        local legacy
        for _,rows in pairs({ns.AthenaWorldScenes.places,ns.AthenaWorldScenes.instances,ns.AthenaWorldScenes.figures}) do
            for _,card in pairs(rows) do if card.title==a.title then
                legacy=card.key or Slug(card.title);a.fields.context=card.body
                a.fieldSources=a.fieldSources or {};a.fieldSources.context=card.sourceURL;a.variants=card.variants
                if card.requiredQuestMention then a.gate='QUEST_MENTION';a.requiredMentions=card.title=='Wailing Caverns' and {'Naralex'} or {'Arugal','worgen'} end
            end end
        end
        if not legacy and (a.title=='Elwynn Forest' or a.title=='Ashenvale' or a.title=='Durotar') then
            legacy=Slug(a.title);local card=ns.AthenaWorldSettings.Get(a.title)
            if card then a.fields.context=a.fields.context or card.body;a.fieldSources=a.fieldSources or {};a.fieldSources.context=card.sourceURL end
        end
        a.id=legacy or 'atlas-'..a.kind..'-'..Slug(a.title);a.zoneCatalog=a.region and true or nil
        D.entries[#D.entries+1]=a;byTitle[a.kind..'/'..a.title]=a
    end
end
local periods={warcraft1={'medivh','guldan','sargeras','llane','garona','blackhand','lothar'},
    warcraft2={'khadgar','doomhammer','turalyon','nerzhul','terenas','deathwing','uther'},
    warcraft3={'illidan','malfurion','cenarius','maiev','vashj','kaelthas','lich-king','cairne','grom','mannoroth','voljin','senjin','azshara','ravencrest','xavius','muradin','archimonde','anubarak','rexxar','rokhan','misha','antonidas','daelin','kiljaeden','malganis'}}
local periodByID={};for period,ids in pairs(periods) do for _,id in ipairs(ids) do periodByID[id]=period end end
for _,e in ipairs(D.entries) do if e.kind=='figure' then e.period=e.period or periodByID[e.id] or 'classic' end end
